class Actor(models.Model):
    films = models.ManyToManyField("Film", through="FilmActor", related_name="actors")

class FilmActor(models.Model):
    actor = models.ForeignKey(Actor, on_delete=models.CASCADE)
    film = models.ForeignKey("Film", on_delete=models.CASCADE)
    cast_since = models.DateField(null=True)

    class Meta:
        constraints = [models.UniqueConstraint(fields=["actor", "film"], name="uniq_actor_film")]
